const app=document.querySelector('#app');
let archive,activeIndex=0,slideIndex=0,filmstrip=null,lastProject=null,photoObserver=null;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>String(n).padStart(2,'0');
const reference=p=>archive.references.find(r=>r.id===p.referenceId);
const safeUrl=s=>{try{const u=new URL(s,location.href);return ['http:','https:'].includes(u.protocol)?escape(s):'#'}catch{return '#'}};
function SiteHeader(view){return `<header class="site-header"><a class="wordmark" href="#" aria-label="Szymon Keller — índice">Szymon Keller</a><p class="header-sub">Referencias para una conversación</p><nav class="site-nav" aria-label="Navegación principal"><a href="#" ${view==='index'?'aria-current="page"':''}>Índice</a><a href="#fuentes" ${view==='sources'?'aria-current="page"':''}>Fuentes y notas</a></nav></header>`}
function ProjectStack(p,i){const r=reference(p);const layers=Array.from({length:Math.min(4,Math.max(3,p.images.length))},(_,j)=>p.images[j%p.images.length]);return `<a class="project-card" href="#proyecto/${escape(p.id)}" aria-label="${escape(r.name)} — ${escape(p.title)}"><span class="card-number">${number(i+1)}</span><span class="image-stack" aria-hidden="true">${layers.slice().reverse().map((im,k)=>`<img class="stack-image" style="--layer:${layers.length-k-1}" src="${safeUrl(im.src)}" alt="" loading="${i<8?'eager':'lazy'}">`).join('')}</span><dl class="card-meta"><dt>ROLE</dt><dd>${escape(p.role)}</dd><dt>NAME</dt><dd>${escape(r.name)}</dd><dt>PROJECT</dt><dd>${escape(p.title)}</dd></dl></a>`}
function Index(){return `${SiteHeader('index')}<main id="main"><div class="index-intro"><p>Archivo de investigación <span class="muted">/ Dirección de arte</span></p><p>${number(archive.projects.length)} proyectos · ${number(archive.references.length)} referentes</p></div><div class="project-grid">${archive.projects.map(ProjectStack).join('')}</div></main><footer class="index-footer"><span>Selección de referencias · ${escape(archive.edition)}</span><span>Objeto, materia y puesta en escena</span></footer>`}
function SourceCredit(im){return `<div><p>${escape(im.caption)}</p><p class="credit">${escape(im.credit)}</p><a href="${safeUrl(im.source)}" target="_blank" rel="noopener noreferrer">Fuente original ↗</a></div>`}
function Annotation(a){return `<div class="annotation"><span class="annotation-number" aria-hidden="true">${escape(a.number)}</span><p>${escape(a.text)}</p></div>`}
function ImagePlate(im,i){return `<figure class="image-plate" id="imagen-${i+1}" aria-label="Imagen ${i+1}: ${escape(im.alt)}"><div class="photo-field"><img src="${safeUrl(im.src)}" alt="${escape(im.alt)}" ${i>1?'loading="lazy"':''}><span class="image-marker" data-x="${im.annotations[0]?.position?.x??.1}" data-y="${im.annotations[0]?.position?.y??.1}" aria-hidden="true">${number(i+1)}</span></div><figcaption class="plate-caption">${SourceCredit(im)}<div>${im.annotations.map(a=>Annotation({...a,number:number(i+1)})).join('')}</div></figcaption></figure>`}
function ProjectNavigation(p){const next=archive.projects[(activeIndex+1)%archive.projects.length];return `<footer class="detail-footer"><p class="help">Recorrer imágenes con ← → · Esc vuelve al índice</p><div class="slide-controls"><button id="previous-image" aria-label="Imagen anterior">←</button><span id="slide-count" aria-live="polite">01 / ${number(p.images.length)}</span><button id="next-image" aria-label="Imagen siguiente">→</button></div><a class="next-project" href="#proyecto/${escape(next.id)}">${activeIndex===archive.projects.length-1?'Volver al primer proyecto':'Siguiente proyecto'} ↗</a></footer>`}
function ProjectDetail(p){const r=reference(p);const related=archive.projects.filter(x=>x.referenceId===p.referenceId&&x.id!==p.id);return `${SiteHeader('detail')}<main id="main"><div class="detail-heading"><div><p class="eyebrow">${number(activeIndex+1)} / ${escape(p.role)}</p><h1 tabindex="-1">${escape(p.title)}</h1><p class="project-byline">${escape(r.name)}</p></div><span class="detail-count">${number(p.images.length)} ${p.images.length===1?'imagen':'imágenes'}</span></div><div class="detail-stage"><aside class="editorial" aria-label="Notas editoriales"><section class="editorial-block"><h2>OPERACIÓN VISUAL</h2><p>${escape(p.operation)}</p></section><section class="editorial-block application"><h2>PARA SZYMON / PROPUESTA</h2><p>${escape(p.application)}</p></section><section class="fixed-note"><h2>NOTA DE PARTIDA</h2><p>${escape(r.fixedNote)}</p></section>${related.length?`<div class="cross-references"><p>Lecturas cruzadas / ${escape(r.name)}</p>${related.map(x=>`<a href="#proyecto/${escape(x.id)}">${escape(x.title)} ↗</a>`).join('')}</div>`:''}<a class="research-link" href="${safeUrl(p.source)}" target="_blank" rel="noopener noreferrer">Consultar el proyecto original ↗</a></aside><div class="filmstrip" tabindex="0" aria-label="Secuencia horizontal de imágenes">${p.images.map(ImagePlate).join('')}</div></div></main>${ProjectNavigation(p)}`}
function Sources(){return `${SiteHeader('sources')}<main id="main" class="sources-page"><h1>Fuentes y notas</h1><p class="sources-lead">Las notas de partida recogen los criterios de esta reunión. Las operaciones visuales son lecturas editoriales; las aplicaciones a Szymon, propuestas para conversar. La selección reúne fuentes aportadas por Rodrigo y páginas originales enlazadas en cada ficha.</p>${archive.references.map((r,i)=>{const projects=archive.projects.filter(p=>p.referenceId===r.id);return `<section class="source-record"><span class="muted">${number(i+1)}</span><h2>${escape(r.name)}</h2><div><p>${escape(r.fixedNote)}</p><div class="source-links">${projects.map(p=>`<a href="#proyecto/${escape(p.id)}">${escape(p.title)}</a>`).join('')}</div></div></section>`}).join('')}<section class="source-record"><span>—</span><h2>Criterio de archivo</h2><div><p>Se conservan los créditos publicados y su alcance. Si la fuente no identifica al autor de una imagen, se indica «pendiente». Los renders de Plissè Block se identifican como tales. Stacked Series publica un crédito conjunto a Pim Top y Mathijs Labadie: la atribución individual sigue pendiente.</p><p style="margin-top:12px">Líneas abiertas: comparar cómo dos autores encuadran una misma pieza; observar lo que la resina oculta; ensayar un relato donde los objetos se encuentren y se separen.</p></div></section></main>`}
function goSlide(delta){if(!filmstrip)return;const plates=[...filmstrip.querySelectorAll('.image-plate')];const target=Math.max(0,Math.min(plates.length-1,slideIndex+delta));filmstrip.scrollTo({left:plates[target].offsetLeft-plates[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
function updateSlide(){if(!filmstrip)return;const plates=[...filmstrip.querySelectorAll('.image-plate')];const step=plates.length>1?plates[1].offsetLeft-plates[0].offsetLeft:1;slideIndex=Math.min(plates.length-1,Math.max(0,Math.round(filmstrip.scrollLeft/step)));document.querySelector('#slide-count').textContent=`${number(slideIndex+1)} / ${number(plates.length)}`;document.querySelector('#previous-image').disabled=slideIndex===0;document.querySelector('#next-image').disabled=slideIndex===plates.length-1}
function positionMarkers(){document.querySelectorAll(".photo-field").forEach(field=>{const img=field.querySelector("img"),marker=field.querySelector(".image-marker");if(!img||!marker||!img.naturalWidth)return;const scale=Math.min(field.clientWidth/img.naturalWidth,field.clientHeight/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;marker.style.left=((field.clientWidth-w)/2+w*Number(marker.dataset.x))+"px";marker.style.top=((field.clientHeight-h)/2+h*Number(marker.dataset.y))+"px"})}
function render(){photoObserver?.disconnect();const hash=location.hash;filmstrip=null;slideIndex=0;if(hash.startsWith('#proyecto/')){const id=hash.slice(10);activeIndex=archive.projects.findIndex(p=>p.id===id);if(activeIndex<0){app.innerHTML=`${SiteHeader('')}<main class="fatal"><h1>Este proyecto no está en el archivo.</h1><a href="#">Volver al índice</a></main>`;return}const p=archive.projects[activeIndex];lastProject=p.id;app.innerHTML=ProjectDetail(p);document.title=`${p.title} — Szymon Keller`;filmstrip=document.querySelector('.filmstrip');filmstrip.addEventListener('scroll',updateSlide,{passive:true});document.querySelector('#previous-image').onclick=()=>goSlide(-1);document.querySelector('#next-image').onclick=()=>goSlide(1);updateSlide();document.querySelector('h1').focus({preventScroll:true})}else if(hash==='#fuentes'){app.innerHTML=Sources();document.title='Fuentes y notas — Szymon Keller'}else{app.innerHTML=Index();document.title='Szymon Keller — Referencias';if(lastProject)document.querySelector(`a[href="#proyecto/${lastProject}"]`)?.focus({preventScroll:true})}window.scrollTo(0,0);photoObserver=new ResizeObserver(positionMarkers);document.querySelectorAll(".photo-field").forEach(field=>photoObserver.observe(field));document.querySelectorAll(".photo-field img").forEach(img=>img.addEventListener("load",positionMarkers));positionMarkers();document.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{if(img.closest('.photo-field')){const message=document.createElement('p');message.className='image-unavailable';message.textContent='Imagen no disponible. Consultá la fuente original en el pie.';img.replaceWith(message)}else{img.style.visibility='hidden'}},{once:true}))}
window.addEventListener('hashchange',()=>{if(archive)render()});window.addEventListener('keydown',e=>{if(!filmstrip||e.altKey||e.metaKey||e.ctrlKey)return;if(e.key==='ArrowRight'){e.preventDefault();goSlide(1)}if(e.key==='ArrowLeft'){e.preventDefault();goSlide(-1)}if(e.key==='Escape'){location.hash=''}});
try{const response=await fetch('data/references.json?v=20260910-v6');if(!response.ok)throw Error('Archive unavailable');archive=await response.json();render()}catch{app.innerHTML='<main class="fatal"><h1>No se pudo abrir el archivo.</h1><p>Recargá la página para volver a intentarlo.</p></main>'}
